PUSHF
POP P6
MOV [P1+0], P6
MOV P3, 0
MOV [P1+34], P3
MOV P6, 0
MOV [P1+28], P6
MOV [P1+30], P6
MOV [P1+32], P6
MOV [P1+36], P6
MOV [P1+38], P6
MOV [P1+40], P6
MOV [P1+42], P6
MOV R0, 0
MOV [P1+8], P6
MOV R1, 0
